import{_ as t,c as d,o,ag as r}from"./chunks/framework.DCv_I274.js";const u=JSON.parse('{"title":"Helpers","description":"","frontmatter":{},"headers":[],"relativePath":"reference/helpers.md","filePath":"reference/helpers.md","lastUpdated":null}'),a={name:"reference/helpers.md"};function l(c,e,i,s,n,p){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="helpers" tabindex="-1">Helpers <a class="header-anchor" href="#helpers" aria-label="Permalink to &quot;Helpers&quot;">​</a></h1><p>Small, reusable utilities in <code>app/Helpers</code> and <code>app/Support</code>. Business rules belong in services, not here.</p><h2 id="activityloghelper" tabindex="-1"><code>ActivityLogHelper</code> <a class="header-anchor" href="#activityloghelper" aria-label="Permalink to &quot;`ActivityLogHelper`&quot;">​</a></h2><p><code>ActivityLogHelper::log(array $logData): void</code>. Writes one activity log entry with the IP and user agent. See <a href="/architecture/activity-logging">Activity logging</a>.</p><h2 id="fileuploadhelper" tabindex="-1"><code>FileUploadHelper</code> <a class="header-anchor" href="#fileuploadhelper" aria-label="Permalink to &quot;`FileUploadHelper`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th></tr></thead><tbody><tr><td><code>fileUpload(UploadedFile $file, string $feature, ?string $identifier = null, ?string $customFilename = null)</code></td><td>the created <code>FileUpload</code> row; the file is stored on the private disk under a UUID name</td></tr><tr><td><code>delete(?FileUpload $file)</code></td><td>removes the file from disk and its row</td></tr><tr><td><code>fileSize(?FileUpload $file)</code></td><td>bytes, or <code>null</code> if missing</td></tr><tr><td><code>humanReadableSize(?int $bytes)</code></td><td><code>&quot;1.2 MB&quot;</code></td></tr></tbody></table><p>See <a href="/foundations/12-file-uploads">File uploads</a>.</p><h2 id="app-support" tabindex="-1"><code>app/Support</code> <a class="header-anchor" href="#app-support" aria-label="Permalink to &quot;`app/Support`&quot;">​</a></h2><p>Framework-free classes: easy to unit test.</p><table tabindex="0"><thead><tr><th>Class</th><th>Use</th></tr></thead><tbody><tr><td><code>Rbac\\PermissionMatrix</code></td><td>expands permission patterns from <code>data/rbac.php</code> (<code>&#39;*&#39;</code>, per module, per sub-module) and rejects unknown names</td></tr><tr><td><code>Auth\\ClientInfo</code></td><td>IP (validated) and user agent of a request</td></tr><tr><td><code>Auth\\IssuedTokens</code></td><td>result of login / refresh: access token, <code>access_expires_in</code>, raw refresh token, expiry, session row</td></tr></tbody></table><h2 id="laravel-helpers-you-ll-use-constantly" tabindex="-1">Laravel helpers you&#39;ll use constantly <a class="header-anchor" href="#laravel-helpers-you-ll-use-constantly" aria-label="Permalink to &quot;Laravel helpers you&#39;ll use constantly&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Helper</th><th>Example</th></tr></thead><tbody><tr><td><code>config()</code></td><td><code>config(&#39;auth.jwt_ttl&#39;)</code></td></tr><tr><td><code>now()</code></td><td><code>now()-&gt;addMinutes(15)</code> (a Carbon date in the app time zone, UTC)</td></tr><tr><td><code>auth()</code></td><td><code>auth()-&gt;user()</code>, <code>auth(&#39;web&#39;)-&gt;check()</code></td></tr><tr><td><code>request()</code></td><td><code>request()-&gt;ip()</code></td></tr><tr><td><code>route()</code> / <code>url()</code></td><td><code>route(&#39;campuses.index&#39;)</code></td></tr><tr><td><code>Str::</code></td><td><code>Str::uuid()</code>, <code>Str::random(64)</code>, <code>Str::limit($text, 100)</code></td></tr><tr><td><code>collect()</code></td><td><code>collect($rows)-&gt;pluck(&#39;id&#39;)</code></td></tr><tr><td><code>abort()</code></td><td><code>abort(404)</code></td></tr><tr><td><code>logger()</code></td><td><code>logger(&#39;Imported&#39;, [&#39;count&#39; =&gt; $n])</code></td></tr><tr><td><code>dd()</code> / <code>dump()</code></td><td>debugging only, never committed</td></tr></tbody></table>',12)])])}const f=t(a,[["render",l]]);export{u as __pageData,f as default};
